WITH remaining_keys AS (SELECT customer_id FROM orders INTERSECT ALL SELECT customer_id FROM orders WHERE customer_id IN (4, 24)), reconciled AS (SELECT s.* FROM orders s INNER JOIN remaining_keys k ON s.customer_id = k.customer_id) SELECT customer_id, COUNT(*) AS num_rows, SUM(CASE WHEN status = 'COMPLETED' THEN discount ELSE 0 END) AS completed_discount, COUNT(*) AS event_count, COUNT(*) FILTER (WHERE status = 'COMPLETED') AS completed_rows, COUNT(DISTINCT channel) AS distinct_channels, STDDEV_SAMP(discount) AS discount_stddev FROM reconciled GROUP BY customer_id ORDER BY num_rows ASC
